class SolutionMemoized:
    def numDistinct(self, s: str, t: str) -> int:
        memo = {}

        def dfs(i: int, j: int) -> int:
            if j == len(t):
                return 1
            if i == len(s):
                return 0
            if (i, j) not in memo:
                memo[(i, j)] = dfs(i + 1, j)
                if s[i] == t[j]:
                    memo[(i, j)] += dfs(i + 1, j + 1)
            return memo[(i, j)]

        return dfs(0, 0)

