class Solution:
    def numDistinct(self, s: str, t: str) -> int:
        n = len(t)
        dp = [0] * (n + 1)
        dp[n] = 1
        for i in range(len(s) - 1, -1, -1):
            # Move left-to-right over suffix index using a saved diagonal.
            prev_diag = 1
            for j in range(n - 1, -1, -1):
                old = dp[j]
                if s[i] == t[j]:
                    dp[j] += prev_diag
                prev_diag = old
        return dp[0]

